-- DML HOTEL CELOSÍA - Sara Henao Fernández
-- Datos de prueba: 1.281 huéspedes, 23 habitaciones, 14 temporadas y 2.087 reservas.
-- Los estados de las reservas están calculados al 10 de noviembre de 2026.
-- =====================================================

-- DIMENSIÓN HUESPED

-- DIMENSIÓN HABITACION

-- DIMENSIÓN TEMPORADA

-- TABLA DE HECHOS RESERVA

-- Los IDs se insertaron de forma explícita: cada IDENTITY continúa desde el máximo valor cargado
ALTER TABLE huesped MODIFY hd_id_huesped GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE habitacion MODIFY ha_id_habitacion GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE temporada MODIFY tp_id_temporada GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE reserva MODIFY re_id_reserva GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);

COMMIT;
